(() => {
 const F=window.FRTB,m=x=>'£'+Number(x).toFixed(2)+'m',n=x=>Number(x).toFixed(3),pct=x=>(100*x).toFixed(2)+'%',green='#285e46',lime='#9fc774',amber='#c9984d';
 const slider=(id,label,min,max,step,value,unit='£m')=>({id,label,min,max,step,value,unit});
 const bars=(labels,values)=>labels.map((label,i)=>({label,value:values[i],color:[green,lime,amber,'#7b999e'][i%4]}));
 const lessons=[{id:'frtb-map',name:'The capital map',stage:'01 · Foundations',title:'How does exposure become capital?',intro:'FRTB is the Fundamental Review of the Trading Book. Start with the three building blocks of its standardised approach.',chart:'Three charges, three different questions',inputs:[slider('sbm','Sensitivity-based charge',0,100,1,40),slider('drc','Default risk charge',0,100,1,15),slider('rrao','Residual risk add-on',0,20,.5,2)],challenge:'Set residual risk to zero. Why can default risk still remain?',formula:'SA = SBM + DRC + RRAO',key:'SA is called the advanced standardised approach in this PRA document.',simpleTitle:'A risk map with more than one layer',simple:'A small market move, an issuer default and a hard-to-model payoff are different sources of loss. FRTB puts them in different layers rather than expecting a single sensitivity to describe all three.',scope:'This opening map accepts already-calculated components. The next lessons construct them. IMA is a separate, permission-based route with desk eligibility tests and standardised fallback.',pages:[[313,'325c · SA components'],[234,'IMA · contents']],compute(s){const total=s.sbm+s.drc+s.rrao;return {stats:[['SA capital',m(total)],['SBM share',total?pct(s.sbm/total):'0%'],['Components','3']],bars:bars(['SBM','DRC','RRAO'],[s.sbm,s.drc,s.rrao]),rows:[['SBM',m(s.sbm),'Delta + vega + curvature, after scenario aggregation'],['DRC',m(s.drc),'Loss on issuer default'],['RRAO',m(s.rrao),'Gross notional charge for residual risks'],['Total',m(total),'Simple sum; no diversification between these layers']],headers:['Layer','Capital','What it captures'],explanation:`The three layers add to ${m(total)}. A hedge can reduce one layer while leaving another intact: matching ordinary price sensitivity does not necessarily eliminate a jump to default or a barrier payoff.`,note:'Capital amounts are separate from risk-weighted assets. These sliders are an introduction, not a portfolio calculation.'};}}];
 window.FRTB_LESSONS=lessons;window.FRTB_UI={slider,bars,m,n,pct,green,lime,amber};
})();
